package com.acme.worker

import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicReference
import java.util.concurrent.locks.ReentrantReadWriteLock
import kotlin.concurrent.read
import kotlin.concurrent.write

data class AuditEntry(val jobId: String, val action: String, val timestamp: Long, val userId: String)
data class JobContext(val jobId: String, val userId: String, val permissions: Set<String>)

object AuditLog {
    private val entries = mutableListOf<AuditEntry>()
    private val lock = ReentrantReadWriteLock()

    fun append(entry: AuditEntry) {
        lock.write { entries.add(entry) }
    }

    fun getEntriesForJob(jobId: String): List<AuditEntry> {
        lock.read { return entries.filter { it.jobId == jobId } }
    }
}

class JobStateManager {
    private val activeJobs = ConcurrentHashMap<String, AtomicReference<JobState>>()

    enum class JobState { PENDING, AUTHORIZED, EXECUTING, COMPLETED, FAILED }

    fun initJob(jobId: String): Boolean {
        val ref = AtomicReference(JobState.PENDING)
        return activeJobs.putIfAbsent(jobId, ref) == null
    }

    fun transitionTo(jobId: String, expected: JobState, next: JobState): Boolean {
        val ref = activeJobs[jobId] ?: return false
        return ref.compareAndSet(expected, next)
    }

    fun getState(jobId: String): JobState? = activeJobs[jobId]?.get()

    fun removeJob(jobId: String) { activeJobs.remove(jobId) }
}

interface AuthorizationService {
    fun checkPermission(userId: String, requiredPermission: String): Boolean
}

class BackgroundJobWorker(
    private val stateManager: JobStateManager,
    private val authService: AuthorizationService
) {
    private val jobContexts = ConcurrentHashMap<String, JobContext>()

    fun submitJob(jobId: String, userId: String, permissions: Set<String>): Boolean {
        if (!stateManager.initJob(jobId)) return false
        val ctx = JobContext(jobId, userId, permissions)
        jobContexts[jobId] = ctx
        AuditLog.append(AuditEntry(jobId, "SUBMITTED", System.nanoTime(), userId))
        return true
    }

    fun authorizeJob(jobId: String): Boolean {
        val ctx = jobContexts[jobId] ?: return false
        val requiredPerm = resolveRequiredPermission(ctx)

        if (!authService.checkPermission(ctx.userId, requiredPerm)) {
            AuditLog.append(AuditEntry(jobId, "AUTH_DENIED", System.nanoTime(), ctx.userId))
            stateManager.transitionTo(jobId, JobStateManager.JobState.PENDING, JobStateManager.JobState.FAILED)
            return false
        }

        val transitioned = stateManager.transitionTo(
            jobId, JobStateManager.JobState.PENDING, JobStateManager.JobState.AUTHORIZED
        )
        if (transitioned) {
            AuditLog.append(AuditEntry(jobId, "AUTHORIZED", System.nanoTime(), ctx.userId))
        }
        return transitioned
    }

    fun executeJob(jobId: String): Boolean {
        val ctx = jobContexts[jobId] ?: return false

        // Verify authorization state before execution
        val currentState = stateManager.getState(jobId)
        if (currentState != JobStateManager.JobState.AUTHORIZED) {
            AuditLog.append(AuditEntry(jobId, "EXEC_REJECTED_STATE", System.nanoTime(), ctx.userId))
            return false
        }

        // Log the execution attempt with current context
        AuditLog.append(AuditEntry(jobId, "EXEC_STARTED", System.nanoTime(), ctx.userId))

        // Perform state transition for execution
        val transitioned = stateManager.transitionTo(
            jobId, JobStateManager.JobState.AUTHORIZED, JobStateManager.JobState.EXECUTING
        )

        if (!transitioned) {
            return false
        }

        // Execute the privileged operation
        performPrivilegedWork(ctx)

        stateManager.transitionTo(jobId, JobStateManager.JobState.EXECUTING, JobStateManager.JobState.COMPLETED)
        AuditLog.append(AuditEntry(jobId, "COMPLETED", System.nanoTime(), ctx.userId))
        return true
    }

    fun reassignJob(jobId: String, newUserId: String, newPermissions: Set<String>): Boolean {
        val oldCtx = jobContexts[jobId] ?: return false
        val state = stateManager.getState(jobId)

        // Only allow reassignment of pending jobs
        if (state != JobStateManager.JobState.PENDING) {
            AuditLog.append(AuditEntry(jobId, "REASSIGN_DENIED", System.nanoTime(), oldCtx.userId))
            return false
        }

        val newCtx = JobContext(jobId, newUserId, newPermissions)
        jobContexts[jobId] = newCtx
        AuditLog.append(AuditEntry(jobId, "REASSIGNED", System.nanoTime(), newUserId))
        return true
    }

    private fun resolveRequiredPermission(ctx: JobContext): String {
        return if (ctx.permissions.contains("admin")) "admin.execute" else "user.execute"
    }

    private fun performPrivilegedWork(ctx: JobContext) {
        // Simulates privileged operation using the job context
        Thread.sleep(10)
    }

    fun cleanup(jobId: String) {
        stateManager.removeJob(jobId)
        jobContexts.remove(jobId)
    }
}
